# Generated by manage.py generate_test_cases.
"""Calendar navigation on the existing Inbox toolbar."""

from django.urls import reverse

from bloomerp.tests.base import BloomerpViewTestCase, ExpectedResult, RequestScenario
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestInboxView(InboxCalendarFixtures, BloomerpViewTestCase):
    view_name = "inbox"

    def extendedSetup(self) -> None:
        """Create a selected shared Inbox for toolbar navigation checks."""
        self.prepare_calendar()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Expose the Calendar link only when event dates and placements are readable."""
        return [
            RequestScenario(
                name="Calendar toolbar button uses the effective shared Inbox",
                user=self.actor,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("data-inbox-calendar"),
                        self.contains_text(
                            reverse(
                                "inbox_calendar", kwargs={"inbox_id": self.source.pk}
                            )
                        ),
                    ]
                ),
            ),
            RequestScenario(
                name="Inbox access without calendar permission hides the button",
                user=self.owner,
                expected=ExpectedResult(
                    response_validators=self.does_not_contain_text(
                        "data-inbox-calendar"
                    )
                ),
            ),
        ]
